import numpy as np, math
from rdkit import Chem
from rdkit.Geometry import Point3D
from scipy.spatial.distance import cdist
rw=Chem.RWMol(); coords=[]; edges=[]
def a(el,xyz,charge=0,noh=False):
 at=Chem.Atom(el); at.SetFormalCharge(charge)
 if noh: at.SetNoImplicit(True)
 i=rw.AddAtom(at); coords.append(np.array(xyz,dtype=float));return i
def b(i,j,typ=Chem.BondType.SINGLE):rw.AddBond(i,j,typ);edges.append((i,j))
zr=a('Zr',(0,0,0),noh=True);co=a('Co',(3.9,.10,-.1),noh=True)
nl=a('N',(-2.02,0,0),noh=True)
nt=a('N',(.55,1.77,-.65),noh=True)
nr=a('N',(1.52,1.37,.62),noh=True)
nb=a('N',(.7,-1.8,-.5),noh=True)
pt=a('P',(2.10,1.80,-.65),noh=True);pr=a('P',(3.05,1.78,.55),noh=True);pb=a('P',(2.25,-1.70,-.55),noh=True)
zero=Chem.BondType.ZERO
for n in (nl,nt,nr,nb):b(n,zr,zero)
for p in (pt,pr,pb):b(p,co,zero)
b(nt,pt);b(nr,pr,Chem.BondType.DOUBLE);b(nb,pb,Chem.BondType.DOUBLE)
# ipso at angle theta (degrees), center is ipso + 1.40*unit direction, then remainder on regular hexagon
# first vertex is ipso, benzene ring vertex coordinates around center with angle theta+pi, advance 60 degrees
def ring(ipso,center,attach,mesityl=False):
 ipso=np.array(ipso);center=np.array(center)
 dr=ipso-center; rad=np.linalg.norm(dr); nrm=dr/rad
 # generate vertices by rotating relative to y-axis in XY plane
 arr=[]
 for k in range(6):
  angle=k*np.pi/3
  vec=np.array([dr[0]*math.cos(angle)-dr[1]*math.sin(angle),dr[0]*math.sin(angle)+dr[1]*math.cos(angle),dr[2]])
  pos=center+vec
  arr.append(a('C',pos))
 for k in range(6):b(arr[k],arr[(k+1)%6],Chem.BondType.DOUBLE if k%2==0 else Chem.BondType.SINGLE)
 b(attach,arr[0]);
 if mesityl:
  for j in (1,3,5):
   vec=coords[arr[j]]-center; vec/=np.linalg.norm(vec)
   cc=a('C',coords[arr[j]]+1.51*vec);b(arr[j],cc)
 return arr
# benzene phenyl attached at ring rightmost
ring((-3.43,0,0),(-4.83,0,0),nl)
# upper mesityls, planes z-separated
ring((.45,3.17,-1.26),(.45,4.57,-1.26),nt,True)
ring((1.39,2.88,1.20),(1.39,4.28,1.20),nr,True)
# bottom ring directed downward and leftward, at z below plane
ring((.0,-3.05,-.55),(-.70,-4.26,-.55),nb,True)
# isocyanide Co-C#N-C(CH3)3
ci=a('C',(5.69,.11,-.1),charge=-1,noh=True);ni=a('N',(6.87,.12,-.1),charge=1,noh=True);tc=a('C',(8.32,.12,-.1),noh=True)
b(co,ci,zero);b(ci,ni,Chem.BondType.TRIPLE);b(ni,tc)
for offset in ((.5,1.43,0),(.5,-.715,1.239),(.5,-.715,-1.239)):
 i=a('C',coords[tc]+offset);b(tc,i)
# six isopropyl groups, use random phi and select lowest nonbonded strain for methyl pairs
subs=[(pt,(.5,.05,-1.74)),(pt,(.49,1.58,.73)),(pr,(1.28,.55,1.14)),(pr,(.52,1.30,-1.17)),(pb,(.18,-1.04,-1.49)),(pb,(1.36,.53,-1.08))]
for parent,d in subs:
 d=np.array(d,dtype=float);d=d/np.linalg.norm(d);chpos=coords[parent]+1.83*d
 # basis perpendicular
 axis=np.array([0,0,1.]);
 if abs(np.dot(axis,d))>.88:axis=np.array([0,1.,0])
 u=np.cross(d,axis);u/=np.linalg.norm(u);v=np.cross(d,u)
 existing=np.array(coords)
 best=None
 for phi in np.linspace(0,2*np.pi,72,endpoint=False):
  vv=np.cos(phi)*u+np.sin(phi)*v
  cc1=chpos+1.53*(d/3+np.sqrt(8)/3*vv);cc2=chpos+1.53*(d/3-np.sqrt(8)/3*vv)
  # avoid contacts excluding parent, and avoid core N/P contacts including close CH
  other=np.delete(existing,[parent],axis=0)
  dd=cdist([cc1,cc2],other)
  score=np.sum(np.clip(2.65-dd,0,None)**2)+np.sum(np.clip(2.60-cdist([chpos],other),0,None)**2)
  if best is None or score<best[0]:best=(score,cc1,cc2)
 ch=a('C',chpos);b(parent,ch)
 for pos in best[1:]:i=a('C',pos);b(ch,i)
# Build, add hydrogens
mol=rw.GetMol();conf=Chem.Conformer(mol.GetNumAtoms());
for i,p in enumerate(coords):conf.SetAtomPosition(i,Point3D(*map(float,p)))
mol.AddConformer(conf)
try:Chem.SanitizeMol(mol)
except Exception as e:print('sanitize error',e)
for at in mol.GetAtoms():
 if at.GetSymbol() in ('N','P','Zr','Co'):
  print('atom',at.GetIdx(),at.GetSymbol(),'bonds',[(b.GetOtherAtomIdx(at.GetIdx()),str(b.GetBondType())) for b in at.GetBonds()], 'H',at.GetTotalNumHs())
try:mh=Chem.AddHs(mol,addCoords=True)
except Exception as e:print('addHs failed',e);raise
print('n heavy',len(coords),'with H',mh.GetNumAtoms())
conf=mh.GetConformer(); elems=[at.GetSymbol() for at in mh.GetAtoms()];positions=np.array(conf.GetPositions())
# eliminate severe close nonbonded contacts by print diagnostics
bondd=set(tuple(sorted((x.GetBeginAtomIdx(),x.GetEndAtomIdx()))) for x in mh.GetBonds())
clashes=[]
for i in range(len(coords)):
 for j in range(i+1,len(coords)):
  if (i,j) not in bondd:
   ds=np.linalg.norm(positions[i]-positions[j]);
   if ds<1.55:clashes.append((round(ds,2),i,j,elems[i],elems[j]))
print('clashes',sorted(clashes)[:25]);print('elements', {el:elems.count(el) for el in set(elems)})
with open('answer.xyz','w') as f:
 f.write(f'{len(elems)}\nZr-Co heterobimetallic tris(phosphinimide), explicit hydrogens; Cartesian angstrom\n')
 for el,(x,y,z) in zip(elems,positions): f.write(f'{el:<3s} {x: .7f} {y: .7f} {z: .7f}\n')
